'use strict';

// MODULES //

var logger = require( 'debug' );


// VARIABLES //

var debug = logger( 'c-doctest:generate' );

// Regular expression to match #include directives:
var RE_INCLUDE = /^\s*#include\s+[<"]([^>"]+)[>"]/;

// Regular expression to match "// returns" annotations in the example code:
var RE_RETURNS = /\/\/\s*returns\s+(.*)/;

// Regular expression to match a variable assignment line like:
//   double y = func( args );
//   float y = func( args );
//   int n = func( args );
//   double complex z = func( args );
var RE_ASSIGNMENT = /^\s*(double\s+complex|float\s+complex|double|float|int|int8_t|int16_t|int32_t|int64_t|uint8_t|uint16_t|uint32_t|uint64_t|bool|size_t|unsigned|signed|long|short|char)\s+(\w+)\s*=\s*(.+?)\s*;\s*$/;

// Regular expression to detect the start of a function definition block.
// Matches lines like:
//   static int32_t fcn( void ) {
//   int my_func( int x ) {
//   static double complex scale( double complex x ) {
var RE_FUNC_DEF = /^\s*(?:static\s+)?(?:(?:unsigned|signed|long|short)\s+)?(?:double\s+complex|float\s+complex|double|float|int|int8_t|int16_t|int32_t|int64_t|uint8_t|uint16_t|uint32_t|uint64_t|bool|size_t|char|void)\s+\w+\s*\([^)]*\)\s*\{/;

// Regular expression to extract a function name from a function definition line:
var RE_FUNC_NAME = /(?:static\s+)?(?:(?:unsigned|signed|long|short)\s+)?(?:double\s+complex|float\s+complex|double|float|int|int8_t|int16_t|int32_t|int64_t|uint8_t|uint16_t|uint32_t|uint64_t|bool|size_t|char|void)\s+(\w+)\s*\(/;

// Tag prefix for doctest result output lines:
var RESULT_TAG = '__DOCTEST_RESULT__:';


// MAIN //

/**
 * Generates a C test program from an extracted example.
 *
 * The key design is a **single-pass interleaved** approach: as we walk the raw
 * example lines, each code statement is emitted to `codeLines` and whenever a
 * `// returns` annotation is encountered we insert the corresponding `printf`
 * inline right there . This ensures that for
 * examples with multiple `// returns`, each printf captures the variable's
 * value at that point in the program, not just the final value.
 *
 * @param {Object} example - example object
 * @param {string} example.code - example code
 * @param {Array} example.assertions - array of assertion objects
 * @param {number} example.line - line number in source file
 * @param {string} fpath - source file path (for extracting includes)
 * @param {string} [sourceContent] - original source file content (for extracting #include directives)
 * @param {Object} [options] - options
 * @param {boolean} [options.appendMode=false] - if true, generate only the suffix to append to the source file (for static function support)
 * @returns {string} complete C program source
 */
function generateTestProgram( example, fpath, sourceContent, options ) {
	var appendMode = ( options && options.appendMode ) || false;
	var extraIncludes = ( options && options.extraIncludes ) || [];
	var functionDefs;
	var annotations;
	var codeLines;
	var includes;
	var program;
	var match;
	var vars;
	var line;
	var i;

	debug( 'Generating test program for example at line %d from %s.', example.line, fpath );

	includes = [];
	codeLines = [];
	functionDefs = [];
	annotations = [];
	vars = {};

	// Add any extra includes provided by the caller:
	for ( i = 0; i < extraIncludes.length; i++ ) {
		includes.push( extraIncludes[ i ] );
	}

	// Always include stdio for printf and math for fabs:
	includes.push( '#include <stdio.h>' );
	includes.push( '#include <math.h>' );
	includes.push( '#include <stdlib.h>' );

	// In append mode, the source file's #includes are already present (we are
	// appending to the source), so we only collect #includes from the @example
	// block itself (handled below in the main loop).
	// In normal mode, extract #includes from the source file:
	if ( !appendMode && sourceContent ) {
		var srcLines = sourceContent.split( '\n' );
		for ( i = 0; i < srcLines.length; i++ ) {
			if ( RE_INCLUDE.test( srcLines[ i ] ) ) {
				includes.push( srcLines[ i ].trim() );
			}
		}
	}

	// --- Single-pass interleaved code + printf generation ---
	//
	// Track the most-recently-seen assigned variable so that when we hit a
	// `// returns` line we can immediately emit a printf for it.
	//
	var rawLines = example.code.split( '\n' );
	var inFuncDef = false;
	var braceDepth = 0;
	var funcBlock = [];
	var lastVarName = null; // most-recently-seen assigned variable name
	var lastVarType = null; // C type of that variable (for bool-aware printf)
	var assignMatch;
	var reAssign;

	for ( i = 0; i < rawLines.length; i++ ) {
		line = rawLines[ i ];

		if ( inFuncDef ) {
			funcBlock.push( '#line ' + ( example.line + 1 + i ) + ' "' + fpath + '"\n' + line );
			for ( var ci = 0; ci < line.length; ci++ ) {
				if ( line[ ci ] === '{' ) {
					braceDepth += 1;
				} else if ( line[ ci ] === '}' ) {
					braceDepth -= 1;
				}
			}
			if ( braceDepth === 0 ) {
				// End of function definition block:
				functionDefs.push( funcBlock.join( '\n' ) );
				funcBlock = [];
				inFuncDef = false;
			}
			continue;
		}

		// ── `// returns` annotation: emit printf inline right now ──
		match = RE_RETURNS.exec( line );
		if ( match ) {
			var rawVal = match[ 1 ].trim();
			var isApprox = /^~/.test( rawVal );
			// Strip leading ~ for the stored annotation value:
			var annotVal = isApprox ? rawVal.slice( 1 ).trim() : rawVal;
			annotVal = annotVal.replace( /f$/, '' );
			var annotationStr = isApprox ? '~' + annotVal : annotVal;
			annotations.push({
				'value': annotationStr,
				'line': example.line + 1 + i
			});

			if ( lastVarName ) {
				codeLines.push( '#line ' + ( example.line + 1 + i ) + ' "' + fpath + '"\n' + buildPrintf( lastVarName, lastVarType ) );
			} else {
				debug( 'Could not find variable for `// returns` annotation at line %d of example at line %d in %s.', i, example.line, fpath );
			}
			continue;
		}

		// ── Blank lines: skip ──
		if ( line.trim().length === 0 ) {
			continue;
		}

		// ── #include directives in the example code itself ──
		if ( RE_INCLUDE.test( line ) ) {
			includes.push( line.trim() );
			continue;
		}

		// ── Start of a function definition block — hoist above main() ──
		if ( RE_FUNC_DEF.test( line ) ) {
			inFuncDef = true;
			braceDepth = 0;
			// Prepend #line to the first line of the function definition:
			funcBlock = [ '#line ' + ( example.line + 1 + i ) + ' "' + fpath + '"\n' + line ];
			// Count opening braces on this first line:
			for ( var cj = 0; cj < line.length; cj++ ) {
				if ( line[ cj ] === '{' ) {
					braceDepth += 1;
				} else if ( line[ cj ] === '}' ) {
					braceDepth -= 1;
				}
			}
			if ( braceDepth === 0 ) {
				// Single-line function def (rare but possible):
				functionDefs.push( funcBlock.join( '\n' ) );
				funcBlock = [];
				inFuncDef = false;
			}
			continue;
		}

		// ── Regular code line — emit to main() ──
		// Prepend #line for each code line:
		codeLines.push( '#line ' + ( example.line + 1 + i ) + ' "' + fpath + '"\n\t' + line.trim() );

		// Track the most-recently declared variable (declaration with type prefix):
		assignMatch = RE_ASSIGNMENT.exec( line );
		if ( assignMatch ) {
			lastVarName = assignMatch[ 2 ];
			lastVarType = assignMatch[ 1 ].trim();
			vars[ lastVarName ] = { 'type': lastVarType, 'name': lastVarName };
		} else {
			// Also handle re-assignments without type prefix: `varName = expr;`
			reAssign = /^\s*(\w+)\s*=\s*.+;\s*$/.exec( line );
			if ( reAssign ) {
				// Update lastVarName but preserve lastVarType from the original
				// declaration so bool-aware printf still works after reassignment:
				lastVarName = reAssign[ 1 ];
				if ( vars[ lastVarName ] ) {
				lastVarType = vars[ lastVarName ].type;
				}
			}
		}
	}

	// In append mode, apply prefix guard: if a hoisted function name already
	// exists in the source file, prefix it with `__doctest_` to avoid
	// redefinition errors, and update all references in codeLines:
	if ( appendMode && sourceContent && functionDefs.length > 0 ) {
		for ( var fi = 0; fi < functionDefs.length; fi++ ) {
			var fnMatch = RE_FUNC_NAME.exec( functionDefs[ fi ] );
			if ( fnMatch ) {
				var fnName = fnMatch[ 1 ];
				// Check if this function name appears in the source content
				// as a function definition (not just in comments):
				var fnCheckRe = new RegExp( '\\b' + fnName + '\\s*\\(', 'g' );
				if ( fnCheckRe.test( sourceContent ) ) {
					var newName = '__doctest_' + fnName;
					debug( 'Hoisted function "%s" conflicts with source; renaming to "%s".', fnName, newName );
					var renameRe = new RegExp( '\\b' + fnName + '\\b', 'g' );
					functionDefs[ fi ] = functionDefs[ fi ].replace( renameRe, newName );
					// Also rename in code lines:
					for ( var cli = 0; cli < codeLines.length; cli++ ) {
						codeLines[ cli ] = codeLines[ cli ].replace( renameRe, newName );
					}
				}
			}
		}
	}

	// Build the complete program string:
	program = '';

	// In append mode, always include stdio/math/stdlib (system headers have
	// include guards, so double inclusion is safe). Then add any extra includes
	// from the @example block that aren't already in the source.
	// NOTE: We cannot use naive indexOf to check whether the source file has an
	// include, because the string `#include <stdio.h>` may appear inside JSDoc
	// comments (e.g. `* #include <stdio.h>`) without being a real directive.
	var uniqueIncludes = deduplicateIncludes( includes );
	if ( appendMode ) {
		// Always emit the three standard includes:
		program += '#include <stdio.h>\n';
		program += '#include <math.h>\n';
		program += '#include <stdlib.h>\n';

		// Emit any extra includes from the @example block:
		for ( i = 0; i < uniqueIncludes.length; i++ ) {
			// Skip the three already emitted:
			if (uniqueIncludes[ i ] === '#include <stdio.h>' ||
				uniqueIncludes[ i ] === '#include <math.h>' ||
				uniqueIncludes[ i ] === '#include <stdlib.h>') {
				continue;
			}
			program += uniqueIncludes[ i ] + '\n';
		}
		program += '\n';
	} else {
		program += uniqueIncludes.join( '\n' ) + '\n\n';
	}

	// Emit any hoisted function definitions before main():
	if ( functionDefs.length > 0 ) {
		program += functionDefs.join( '\n\n' ) + '\n\n';
	}

	program += 'int main( void ) {\n';

	for ( i = 0; i < codeLines.length; i++ ) {
		program += codeLines[ i ] + '\n';
	}
	program += '\treturn EXIT_SUCCESS;\n';
	program += '}\n';

	debug( 'Generated test program:\n%s', program );

	return {
		'program': program,
		'annotations': annotations
	};
}

/**
 * Builds a `printf` statement for the given variable.
 *
 *
 * @private
 * @param {string} varName - variable name
 * @param {string} varType - C type of the variable (e.g. "double", "bool")
 * @returns {string} printf statement (with leading tab, no trailing newline)
 */
function buildPrintf( varName, varType ) {
	if ( varType === 'bool' ) {
		// Print the string "true" or "false" so it matches annotations like
		// `// returns true` and `// returns false`.
		return '\tprintf( "' + RESULT_TAG + '%s\\n", (' + varName + ') ? "true" : "false" );';
	}
	// Default: cast to double and print with full precision.
	return '\tprintf( "' + RESULT_TAG + '%.17g\\n", (double)' + varName + ' );';
}

/**
 * Deduplicates include directives.
 *
 * @private
 * @param {StringArray} includes - array of include directives
 * @returns {StringArray} deduplicated includes
 */
function deduplicateIncludes( includes ) {
	var seen = {};
	var result = [];
	var i;

	for ( i = 0; i < includes.length; i++ ) {
		if ( !seen[ includes[ i ] ] ) {
			seen[ includes[ i ] ] = true;
			result.push( includes[ i ] );
		}
	}
	return result;
}


// EXPORTS //

module.exports = generateTestProgram;
